// Recorded voice bank (ElevenLabs, fixed text written by the project; never chat text or usernames).
// Boss taunts in Boss Fight; coach calls for the Crowd Trainer. Generated by scripts/voice-bank.py from
// assets/voice/bank/lines.json. Only the chosen voice's files are ever fetched, one line at a time.
import type {GameState} from '../../shared/src/engine';
import type {ImportGlobFunction} from 'vite/types/importGlob.d.ts';
// Only Vite's glob is declared here; demo/src/twitch/auth.ts owns import.meta.env.
declare global{interface ImportMeta{readonly glob:ImportGlobFunction}}

export type Bank='boss'|'coach';
export const BOSS_CUES=['taunt-round-start','taunt-hit','taunt-blocked','taunt-dodged','taunt-perfect','taunt-habit-left','taunt-habit-right','taunt-super','taunt-finisher','taunt-round-win','taunt-round-lose','taunt-quiet-chat'] as const;
export const COACH_CUES=['combo-12','combo-112','combo-121','combo-1212','combo-12s','combo-s12','combo-12g','combo-2s2','round-start','rest','ten-seconds','time','clean','partial','missed','faster','slower','workout-done','chat-picked'] as const;
export type BossCue=typeof BOSS_CUES[number];
export type CoachCue=typeof COACH_CUES[number];
export type VoiceOption={id:string;name:string};
/** Mirrors voices in assets/voice/bank/lines.json (a test keeps them equal); files live in assets/voice/bank/<id>/. */
export const VOICES:Record<Bank,VoiceOption[]>={boss:[{id:'golem',name:'Stone Golem'},{id:'gremlin',name:'Gremlin'},{id:'queen',name:'Rock Queen'},{id:'rumble',name:'Big Rumble'}],coach:[{id:'drill',name:'Drill Coach'},{id:'hype',name:'Hype Coach'},{id:'corner',name:'Corner Coach'},{id:'pads',name:'Pad Pro'}]};
export const DEFAULT_VOICE:Record<Bank,string>={boss:'golem',coach:'drill'};
/** Compatible with demo/src/prefs.ts (`svc.prefs.`). Boss may be 'off'; the coach always has a voice. */
export const VOICE_PREF_PREFIX='svc.prefs.voice.';
/** One sample line per bank for the ▶ preview button. */
export const PREVIEW_CUE:Record<Bank,string>={boss:'taunt-round-start',coach:'combo-12'};
/** Never repeat any of the last few lines of a cue (fewer when the cue has fewer variants). */
export const RECENT_LINES=5;
/** The subset of GameSound the bank needs: same mute, limiter and music duck as the announcer. */
export type VoiceHost={readonly enabled:boolean;speaking():boolean;loadBuffer(url:string):Promise<AudioBuffer|undefined>;playBuffer(buffer:AudioBuffer,options?:{yieldToVoice?:boolean}):{stop():void;ended:Promise<void>}|undefined};
type Storage={getItem(key:string):string|null;setItem(key:string,value:string):void};
type Playing={bank:Bank;stop():void};

/** Measured take lengths ({voice:{cue:[seconds]}}, written by `voice-bank.py qc`). They also list every shipped file, and let
 * the player choose a taunt that fits the gap without fetching. */
const bundledDurations=()=>Object.values(import.meta.glob('../../assets/voice/bank/durations.json',{import:'default',eager:true}))[0] as Record<string,Record<string,(number|null)[]>>|undefined??{};
/** voice id → cue → URLs in variant order. scripts/build-demo.ts copies the bank (about 870 small MP3s) to
 * assets/voice-bank/<voice>/<cue>-<n>.mp3 rather than bundling it, so only the chosen voice is ever fetched. */
export function bankFiles(durations:Record<string,Record<string,unknown[]>>,base:string):Record<string,Record<string,string[]>> {
  return Object.fromEntries(Object.entries(durations).map(([voice,cues])=>[voice,Object.fromEntries(Object.entries(cues).map(([cue,list])=>[cue,list.map((_,index)=>`${base}${voice}/${cue}-${index+1}.mp3`)]))]));
}
const bankBase=()=>{try{return new URL('assets/voice-bank/',location.origin+'/').href;}catch{return 'assets/voice-bank/';}};
export const BANK_SFX=['crowd-cheer','crowd-groan','pad-hit','rest-whistle','big-bell'] as const;
/** URL of a bank sound effect (ElevenLabs Sound Effects) for the Crowd Trainer; play it through GameSound.loadBuffer/playBuffer. */
export const bankSfxUrl=(name:typeof BANK_SFX[number])=>`${bankBase()}sfx/${name}.mp3`;
const browserStorage=():Storage|undefined=>{try{return globalThis.localStorage;}catch{return undefined;}};

export function createVoiceBank(host:VoiceHost,options:{files?:Record<string,Record<string,string[]>>;durations?:Record<string,Record<string,(number|null)[]>>;random?:()=>number;storage?:Storage}={}) {
  const durations=options.durations??bundledDurations(),files=options.files??bankFiles(durations,bankBase()),random=options.random??Math.random,storage=options.storage??browserStorage();
  const buffers=new Map<string,Promise<AudioBuffer|undefined>>(),recent=new Map<string,number[]>();
  let playing:Playing|null=null,pending:{bank:Bank}|null=null;
  const read=(bank:Bank)=>{try{return storage?.getItem(VOICE_PREF_PREFIX+bank)??null;}catch{return null;}};
  const valid=(bank:Bank,id:string|null)=>id!==null&&(bank==='boss'&&id==='off'||VOICES[bank].some(voice=>voice.id===id));
  const voices:Record<Bank,string>={boss:valid('boss',read('boss'))?read('boss')!:DEFAULT_VOICE.boss,coach:valid('coach',read('coach'))?read('coach')!:DEFAULT_VOICE.coach};
  /** Shuffle bag: a random variant that is not one of the last few played for this voice and cue and
   * (when its measured length is known) fits `maxSeconds`. Undefined when none fits; the bag is untouched. */
  function pick(voice:string,cue:string,maxSeconds=Infinity):string|undefined{
    const urls=files[voice]?.[cue];if(!urls?.length)return undefined;
    const key=`${voice}:${cue}`,last=recent.get(key)??[],avoid=last.slice(-Math.min(RECENT_LINES,urls.length-1)),lengths=durations[voice]?.[cue];
    const open=urls.map((_,index)=>index).filter(index=>!avoid.includes(index)&&(lengths?.[index]??0)<=maxSeconds);
    if(!open.length)return undefined;
    const index=open[Math.floor(random()*open.length)]!;
    recent.set(key,[...last,index].slice(-RECENT_LINES));return urls[index];
  }
  const load=(url:string)=>{let buffer=buffers.get(url);if(!buffer){buffer=host.loadBuffer(url).then(result=>{if(!result)buffers.delete(url);return result;});buffers.set(url,buffer);}return buffer;};
  function stop(bank?:Bank){if(playing&&(!bank||playing.bank===bank)){const line=playing;playing=null;line.stop();}if(!bank||pending?.bank===bank)pending=null;}
  /** Play one line in the chosen voice: the first of `cues` with a take that fits. Never overlaps itself:
   * a line already playing (or loading) wins unless `interrupt`. `maxSeconds` keeps the line inside the gap
   * it must fit; `allowed` is re-checked after the lazy load. Resolves to the cue that started, or null. */
  async function playLine(bank:Bank,cues:string|readonly string[],opts:{interrupt?:boolean;maxSeconds?:number;allowed?:()=>boolean;yieldToVoice?:boolean}={}):Promise<string|null>{
    const voice=voices[bank];
    if(voice==='off'||!host.enabled)return null;
    if(playing||pending){if(!opts.interrupt)return null;stop();}
    let cue:string|undefined,url:string|undefined;
    for(const candidate of typeof cues==='string'?[cues]:cues){url=pick(voice,candidate,opts.maxSeconds);if(url){cue=candidate;break;}}
    if(!cue||!url)return null;
    // A per-call ticket: a later interrupting call (even on the same bank) invalidates this one's load.
    const ticket={bank};pending=ticket;const buffer=await load(url);
    if(pending!==ticket||!buffer||voices[bank]!==voice||!host.enabled||opts.allowed&&!opts.allowed()){if(pending===ticket)pending=null;return null;}
    pending=null;
    if(opts.maxSeconds!==undefined&&buffer.duration>opts.maxSeconds)return null;
    const line=host.playBuffer(buffer,{yieldToVoice:opts.yieldToVoice??bank==='boss'});if(!line)return null;
    const entry:Playing={bank,stop:()=>line.stop()};playing=entry;void line.ended.then(()=>{if(playing===entry)playing=null;});
    return cue;
  }
  function setVoice(bank:Bank,id:string){if(!valid(bank,id))return;voices[bank]=id;stop(bank);try{storage?.setItem(VOICE_PREF_PREFIX+bank,id);}catch{/* Private mode: the choice lasts this page only. */}}
  return {playLine,stop,setVoice,voice:(bank:Bank)=>voices[bank],busy:()=>!!playing||!!pending,
    /** URL of one preview line for an <audio> element before game sound has started. */
    previewUrl(bank:Bank):string|undefined{const voice=voices[bank];return voice==='off'?undefined:pick(voice,PREVIEW_CUE[bank]);}};
}
export type VoiceBank=ReturnType<typeof createVoiceBank>;

let current:VoiceBank|null=null;
/** Crowd Trainer hook for the integrator: speak a coach cue in the chosen coach voice, cutting off the previous call. */
export function playCoach(cue:CoachCue):Promise<boolean>{return current?current.playLine('coach',cue,{interrupt:true,yieldToVoice:false}).then(Boolean):Promise.resolve(false);}
export function setActiveVoiceBank(bank:VoiceBank|null){current=bank;}

/** Boss taunts are the lowest-priority voice: only when nothing else speaks, at most one per TAUNT_GAP_MS,
 * never while an attack is telegraphed or landing (don't distract the defence), and cut off by a new warning. */
export const TAUNT={gapMs:6000,quietMs:15000,routineChance:.6,ttlMs:2500,endTtlMs:5000,beatMarginMs:250} as const;
const priority:Record<BossCue,number>={'taunt-habit-left':9,'taunt-habit-right':9,'taunt-finisher':8,'taunt-super':7,'taunt-round-win':6,'taunt-round-lose':6,'taunt-perfect':5,'taunt-hit':3,'taunt-blocked':3,'taunt-dodged':3,'taunt-round-start':2,'taunt-quiet-chat':1};
const routine=new Set<BossCue>(['taunt-hit','taunt-blocked','taunt-dodged']);
export function createBossTaunts(bank:Pick<VoiceBank,'playLine'|'stop'|'busy'>,host:Pick<VoiceHost,'speaking'>,options:{now?:()=>number;random?:()=>number}={}) {
  const clock=options.now??(()=>performance.now()),random=options.random??Math.random;
  let previous:GameState|undefined,habitTold:string|null=null,want:{cue:BossCue;until:number}|null=null,lastTauntAt=-Infinity,lastVoteAt=0,quietTaunted=false,attempting=false,enabled=true;
  const warning=(state:GameState)=>!!state.activeAttack&&!state.activeAttack.vetoed;
  const queue=(cue:BossCue,now:number,ttl:number=TAUNT.ttlMs)=>{if(routine.has(cue)&&random()>=TAUNT.routineChance)return;if(!want||priority[cue]>=priority[want.cue]||want.until<now)want={cue,until:now+ttl};};
  function events(state:GameState,before:GameState,now:number){
    const resolved=state.log.resolved.length>before.log.resolved.length?state.log.resolved.at(-1):undefined;
    if(resolved)queue(resolved.outcome==='BLOCK'?'taunt-blocked':resolved.outcome==='DODGE'?'taunt-dodged':resolved.outcome==='PERFECT'?'taunt-perfect':'taunt-hit',now);
    if(state.hype>=100&&before.hype<100)queue('taunt-super',now);
    if(state.log.finishers.length>before.log.finishers.length)queue('taunt-finisher',now);
    if(state.round.number>before.round.number)queue('taunt-round-start',now);
    if(state.log.rounds.length>before.log.rounds.length)queue(state.log.rounds.at(-1)!.winner==='boss'?'taunt-round-win':'taunt-round-lose',now,TAUNT.endTtlMs);
  }
  function quiet(state:GameState,now:number){
    if(state.voters>0||Object.values(state.tally).some(count=>count>0)){lastVoteAt=state.now;quietTaunted=false;return;}
    if(!quietTaunted&&!state.round.over&&!state.paused&&state.now-lastVoteAt>=TAUNT.quietMs){quietTaunted=true;queue('taunt-quiet-chat',now);}
  }
  function observeState(state:GameState|null){
    const now=clock();
    if(!state){previous=undefined;want=null;bank.stop('boss');return;}
    const before=previous;previous=state;
    // A new match, restart or rewind primes silently: old events never replay as taunts.
    if(!before||state.match.seed!==before.match.seed||state.round.number<before.round.number||state.log.rounds.length<before.log.rounds.length){
      want=null;habitTold=state.scouting.card;lastVoteAt=state.now;quietTaunted=false;bank.stop('boss');
      if(!state.round.over&&state.round.elapsed_ms<1000)queue('taunt-round-start',now);
      return;
    }
    events(state,before,now);quiet(state,now);
    const card=state.scouting.card;if(!card)habitTold=null;
    if(warning(state)){bank.stop('boss');return;}
    if(want&&want.until<now)want=null;
    // A visible habit card keeps asking until one habit taunt fits a gap (the card can last several beats);
    // when none fits, the queued event taunt is tried instead.
    const cues:BossCue[]=[...(card&&habitTold!==card?[card==='L'?'taunt-habit-left' as const:'taunt-habit-right' as const]:[]),...(want?[want.cue]:[])];
    if(!enabled||!cues.length||attempting)return;
    if(state.paused||now-lastTauntAt<TAUNT.gapMs||host.speaking()||bank.busy())return;
    // The whole line must finish before the next beat's warning.
    const budget=state.round.over?undefined:(state.clock.next_beat-state.now-TAUNT.beatMarginMs)/1000;
    if(budget!==undefined&&budget<=.5)return;
    attempting=true;
    void bank.playLine('boss',cues,{maxSeconds:budget,allowed:()=>!!previous&&!warning(previous)&&!previous.paused}).then(cue=>{attempting=false;if(!cue)return;lastTauntAt=clock();if(cue==='taunt-habit-left')habitTold='L';else if(cue==='taunt-habit-right')habitTold='R';if(want?.cue===cue)want=null;});
  }
  // A voice failure never blocks gameplay: observe runs inside the game's paint.
  const observe=(state:GameState|null)=>{try{observeState(state);}catch{attempting=false;}};
  return {observe,setEnabled(value:boolean){enabled=value;if(!value){want=null;bank.stop('boss');}}};
}

/** "Boss voice: [Off | …] ▶" and "Coach voice: […] ▶" beside the existing Sound switch. Small and additive. */
export function mountVoicePicker(after:Element,bank:VoiceBank,options:{preview:(bank:Bank)=>void}){
  const doc=after.ownerDocument,box=doc.createElement('div');box.className='voice-picker defence-only';
  const row=(kind:Bank,label:string)=>{
    const choices=(kind==='boss'?[{id:'off',name:'Off'}]:[]).concat(VOICES[kind]);
    const wrap=doc.createElement('div');wrap.className='voice-row';
    wrap.innerHTML=`<label for="${kind}-voice">${label}</label><select id="${kind}-voice">${choices.map(voice=>`<option value="${voice.id}">${voice.name}</option>`).join('')}</select><button type="button" class="voice-preview" data-bank="${kind}" aria-label="Preview ${label.toLowerCase()}" title="Preview">▶</button>`;
    const select=wrap.querySelector('select')!,play=wrap.querySelector('button')!;
    const sync=()=>{select.value=bank.voice(kind);play.disabled=select.value==='off';};
    select.addEventListener('change',()=>{bank.setVoice(kind,select.value);sync();select.blur();});
    play.addEventListener('click',()=>{options.preview(kind);play.blur();});
    sync();return wrap;
  };
  box.append(row('boss','Boss voice'),row('coach','Coach voice'));after.after(box);return box;
}
